create table service_order_items (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, service_order_id uuid not null, type text not null, description text not null, quantity numeric(14,3) not null, unit_price numeric(14,2) not null, discount_amount numeric(14,2) not null default 0, total_amount numeric(14,2) generated always as (round(quantity*unit_price-discount_amount,2)) stored, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(tenant_id,id), foreign key(tenant_id,service_order_id) references service_orders(tenant_id,id), check(type in ('service','part')), check(quantity>0), check(unit_price>=0), check(discount_amount>=0), check(discount_amount<=quantity*unit_price));
create index service_order_items_order_idx on service_order_items(tenant_id,service_order_id);
alter table service_order_items enable row level security; alter table service_order_items force row level security;
create policy service_order_items_tenant_isolation on service_order_items using(tenant_id=current_setting('app.tenant_id',true)::uuid) with check(tenant_id=current_setting('app.tenant_id',true)::uuid);
grant select,insert,update,delete on service_order_items to vetoros_runtime;
